window.VO = [{"id":"n01","text":"You're the judge.","at":0.24,"t0":0.12,"t1":1.02},{"id":"n02","text":"In a city of two crore people, someone robbed a woman at a chai stall.","at":2.54,"t0":1.27,"t1":5.06},{"id":"n03","text":"Nobody saw his face, but he cut his hand on a glass, and the blood matches this man.","at":10.62,"t0":5.31,"t1":10.085},{"id":"p01","text":"Your Honour, only one person in ten thousand has this blood.","at":21.27,"t0":10.635,"t1":14.475},{"id":"p02","text":"That's a one in ten thousand chance it was someone else.","at":29.45,"t0":14.725,"t1":17.755},{"id":"n04","text":"The blood is all there is. Guilty, or not guilty?","at":36.31,"t0":18.155,"t1":21.21},{"id":"d01","text":"Judge sahab, I wasn't there.","at":43.12,"t0":21.56,"t1":23.16},{"id":"n05","text":"One in ten thousand. And he matches.","at":46.92,"t0":23.46,"t1":25.82},{"id":"n06","text":"You had two numbers. Did you put them together?","at":53.64,"t0":26.82,"t1":29.275},{"id":"n07","text":"Two crore people. One in ten thousand of them.","at":60.05,"t0":30.025,"t1":32.895},{"id":"n08","text":"That's two thousand people with his blood.","at":66.39,"t0":33.195,"t1":35.29},{"id":"n09","text":"So the blood narrows it down to two thousand. It can't tell you which one.","at":71.78,"t0":35.89,"t1":39.85},{"id":"n10","text":"It's called the prosecutor's fallacy, and it fools real judges too.","at":80.5,"t0":40.25,"t1":44.045},{"id":"n11","text":"One of those two thousand, you've met before.","at":88.99,"t0":44.495,"t1":46.855},{"id":"n12","text":"Four films. Same thief. Still free.","at":94.21,"t0":47.105,"t1":49.37},{"id":"n13","text":"Now try it on the friend who's good at maths. Don't tell them it's maths.","at":99.74,"t0":49.87,"t1":53.565},{"id":"n14","text":"So. Where was the thief sitting?","at":107.93,"t0":53.965,"t1":55.61}];
